// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar la ficha (página 2). F1, 2026-10-12.
// F4, 2026-10-13: añade aviso_tecnico y codigo a la salida (errores técnicos -> WF4).
// v2, 2026-10-14 (D33): sin atributos style (n8n los borra) y añade nombre y
//   tipo_reforma a la salida: los usa preparar_calendario para el evento de WF5.
// Entrada ($json): la respuesta COMPLETA de GET /oportunidades/{id}/ficha,
//   es decir { statusCode, headers, body } (opción "Include Response Headers
//   and Status" del nodo leer_ficha).
// Salida: { resultado, mensaje, ficha_html, oportunidad_id, tipo_llamada,
//           resultados, visita_pedida, aviso_tecnico, codigo }, donde resultado es:
//   'ok'            -> hay una llamada que registrar: se enseña la ficha
//   'ya_registrado' -> ya tiene un resultado (es definitivo): aviso y fin
//   'nada'          -> no tiene ninguna llamada pendiente: aviso y fin
//   'error'         -> el backend no respondió 200: aviso y fin
//   aviso_tecnico   -> true si el error es técnico (lo lee preparar_aviso_tecnico)
// QUIÉN DECIDE qué se puede registrar: el backend (llamada_registrable).
// Este nodo no deduce nada. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP de la respuesta (200, 404, 422...).
const estado = $json.statusCode;
// Cuerpo de la respuesta; "?? {}" = objeto vacío si no hay cuerpo.
const b = $json.body ?? {};

// Escapar texto antes de meterlo en HTML: nombre, texto de la visita...
// los escribió el CLIENTE en el chat, y podrían llevar código HTML.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < y > : impiden abrir etiquetas HTML
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')   // comillas: impiden salir de un atributo
    .replace(/'/g, '&#39;');
}

// Atajo para devolver una salida completa; "extra" sustituye los valores por defecto.
function salida(resultado, mensaje, extra = {}) {
  return {
    json: {
      resultado,                                   // 'ok', 'ya_registrado', 'nada' o 'error'
      mensaje,                                     // texto para la pantalla de aviso
      ficha_html: '',                              // la ficha (solo en 'ok')
      oportunidad_id: b.oportunidad_id ?? null,    // el número, si el backend lo dio
      tipo_llamada: null,                          // gate, seguimiento o confirmacion_visita
      resultados: [],                              // resultados admitidos (solo en 'ok')
      visita_pedida: null,                         // { fecha, hora, texto } en confirmaciones
      aviso_tecnico: false,                        // NUEVO F4: true = avisar al técnico (WF4)
      codigo: estado,                              // NUEVO F4: código HTTP, para el aviso
      nombre: null,                                // v2: nombre del cliente (título del evento)
      tipo_reforma: null,                          // v2: tipo de reforma (título del evento)
      ...extra,                                    // lo que cambie en cada caso
    },
  };
}

// ---- 1. Respuestas que NO son 200: explicar y terminar ----------------------
if (estado !== 200) {
  let mensaje;                                     // el texto que verá administración
  let aviso_tecnico = false;                       // NUEVO F4: por defecto, error del operador
  if (estado === 404) {
    // Número que no existe: lo arregla el operador. Sin aviso técnico.
    mensaje = 'No existe ninguna oportunidad con ese número. Revisa el número de la lista diaria.';
  } else if (estado === 422) {
    // Número mal escrito: lo arregla el operador. Sin aviso técnico.
    mensaje = 'El número de oportunidad no es válido.';
  } else if (estado === 401) {
    // Llave mala: el formulario está roto para TODOS los casos -> aviso técnico.
    mensaje = 'Error de configuración: el formulario no tiene una llave válida. Avisa al responsable técnico.';
    aviso_tecnico = true;
  } else {
    // 500, 503... : fallo del sistema, el operador no puede arreglarlo -> aviso técnico.
    mensaje = `Error inesperado del sistema (código ${estado}). Inténtalo de nuevo en unos minutos.`;
    aviso_tecnico = true;
  }
  return salida('error', mensaje, { oportunidad_id: null, aviso_tecnico });
}

// ---- 2. Formatos y diccionarios (solo para MOSTRAR) -------------------------
// Euros y números en formato español.
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });
// Un importe, o una raya si no hay.
function dinero(t) { return (t === null || t === undefined) ? '—' : eur.format(Number(t)); }
// Una fecha con hora, en hora de Madrid, o una raya si no hay.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
    year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}
// Códigos del backend -> texto legible.
const TIPOS = { bano: 'Baño', cocina: 'Cocina', integral_vivienda: 'Reforma integral de vivienda', parcial_acabados: 'Acabados parciales' };
const ACABADOS = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };
const TIPOS_LLAMADA = { gate: 'Gate (aprobación manual)', seguimiento: 'Seguimiento del presupuesto', confirmacion_visita: 'Confirmación de visita pedida' };
const RESULTADOS = {
  visita_acordada: 'Visita acordada', descartar: 'Descartado', confirmar_hora: 'Hora confirmada',
  otra_hora: 'Otra hora acordada', cliente_cancela: 'El cliente cancela',
};
const MOTIVOS = {
  precio: 'precio', plazo: 'plazo', no_contesta: 'no contesta', proyecto_no_viable: 'proyecto no viable',
  otro: 'otro', sin_decision: 'sin decisión en la última llamada',
};
const ESTADOS = {
  nueva: 'nueva', cualificada: 'cualificada', pendiente_aprobacion: 'pendiente de aprobación',
  visita_agendada: 'visita agendada', presupuesto_enviado: 'presupuesto enviado',
  seguimiento_pendiente: 'seguimiento pendiente', ganada: 'ganada', perdida: 'perdida',
};

// ---- 3. ¿Ya tiene un resultado? Es definitivo: avisar y terminar ------------
// "llamadas" viene ordenada de la más antigua a la más reciente: se toma la última.
const llamadas = b.llamadas ?? [];
if (llamadas.length > 0) {
  const u = llamadas[llamadas.length - 1];
  // Con visita: su fecha. Sin visita (descartar o cancelar): el motivo.
  const detalle = u.fecha_visita
    ? `visita el ${fecha(u.fecha_visita)}`
    : `motivo: ${MOTIVOS[u.motivo] ?? u.motivo ?? '—'}`;
  return salida('ya_registrado',
    `La oportunidad ${b.oportunidad_id} ya tiene un resultado registrado ` +
    `(${RESULTADOS[u.resultado] ?? u.resultado}, ${detalle}; registrado el ${fecha(u.fecha_registro)}). ` +
    `Es definitivo: no hace falta volver a registrarlo.`);
}

// ---- 4. ¿Hay algo que registrar ahora? Lo dice el backend -------------------
const lr = b.llamada_registrable;                  // null o { tipo_llamada, resultados }
if (!lr) {
  return salida('nada',
    `La oportunidad ${b.oportunidad_id} no tiene ninguna llamada pendiente ` +
    `(estado: ${ESTADOS[b.estado_oportunidad] ?? b.estado_oportunidad}).`);
}

// ---- 5. En una confirmación: la visita que pidió el cliente -----------------
// Es la visita con estado 'solicitada'. Su fecha_visita llega en hora de Madrid
// con su desfase ("2026-10-13T11:00:00+02:00"): se recorta el texto en vez de
// convertirlo, para que ninguna zona horaria pueda mover el día o la hora.
let visita_pedida = null;
if (lr.tipo_llamada === 'confirmacion_visita') {
  const v = (b.visitas ?? []).find((x) => x.estado_visita === 'solicitada');
  // Si el backend dice "confirmación" pero no hay visita pedida, algo no cuadra: parar.
  // NUEVO F4: es una incoherencia de datos del sistema -> aviso técnico.
  if (!v) {
    return salida('error',
      `La oportunidad ${b.oportunidad_id} debería tener una visita pedida y no la tiene. Avisa al responsable técnico.`,
      { aviso_tecnico: true });
  }
  visita_pedida = {
    fecha: String(v.fecha_visita).slice(0, 10),    // "2026-10-13"
    hora: String(v.fecha_visita).slice(11, 16),    // "11:00"
    texto: v.texto_cliente ?? '',                  // lo que dijo el cliente
    fecha_legible: fecha(v.fecha_visita),          // para enseñarla
  };
}

// ---- 6. La ficha en HTML ----------------------------------------------------
// Una fila "etiqueta: valor". El valor SIEMPRE pasa por esc().
function fila(etiqueta, valor) {
  // v2 (14/10): sin style (n8n lo elimina); el valor va en negrita.
  return `<tr><td>${etiqueta}</td><td><strong>${esc(valor)}</strong></td></tr>`;
}
const c = b.contacto ?? {};                        // nombre, telefono, origen...
const r = b.reforma ?? {};                         // tipo, m2, acabados...
const p = b.presupuesto;                           // null si no hay presupuesto

// Contacto: el de esta solicitud, o un aviso si la solicitud no lo trae.
let filas = c.origen === 'solicitud'
  ? fila('Cliente', c.nombre ?? '—') + fila('Teléfono', c.telefono ?? '—')
  : fila('Contacto', 'No disponible en la solicitud: revisa la ficha completa');
// Qué llamada es (la decidió el backend).
filas += fila('Llamada', TIPOS_LLAMADA[lr.tipo_llamada] ?? lr.tipo_llamada);
// La reforma: tipo, metros y acabado.
const m2 = (r.m2 === null || r.m2 === undefined) ? '—' : `${num.format(Number(r.m2))} m²`;
filas += fila('Reforma', `${TIPOS[r.tipo_reforma] ?? r.tipo_reforma ?? '—'}, ${m2}, acabado ${ACABADOS[r.nivel_acabados] ?? r.nivel_acabados ?? '—'}`);
// El presupuesto, si existe (el formulario es solo de administración: puede ver importes).
if (p) filas += fila('Horquilla (IVA incl.)', `${dinero(p.importe_min_con_iva)} – ${dinero(p.importe_max_con_iva)}`);
// En una confirmación: la hora pedida y lo que contó el cliente.
if (visita_pedida) {
  filas += fila('Visita pedida', visita_pedida.fecha_legible);
  filas += fila('Lo que dijo el cliente', visita_pedida.texto || '—');
}

// La tarjeta: título en negrita y la tabla (v2: sin style, n8n lo borra).
const ficha_html =
  `<p><strong>Oportunidad ${esc(b.oportunidad_id)}</strong></p>` +   // el número, en negrita
  `<table>${filas}</table>`;                                          // las filas de arriba

// ---- 7. Todo listo: la ficha y lo que necesitarán las páginas siguientes ----
return salida('ok', '', {
  ficha_html,
  tipo_llamada: lr.tipo_llamada,
  resultados: lr.resultados,
  visita_pedida,
  // v2 (D33): para el evento del calendario. Solo el nombre (nunca teléfono ni email).
  nombre: c.origen === 'solicitud' ? (c.nombre ?? null) : null,
  tipo_reforma: r.tipo_reforma ?? null,                // el código (bano, cocina...)
});

// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar el resultado (tras la página del resultado). F2, 2026-10-12.
// D32, 2026-10-14: en "Visita acordada" y "Otra hora", la fecha sale de la página
//   "Día" (vía preparar_pagina_hora) y la hora de la página "Hora". Las lecturas
//   de otros nodos usan .first() (= su ÚLTIMA ejecución): en el bucle de la agenda
//   este nodo puede ejecutarse más de una vez y .item no sirve en bucles.
// Entrada ($json): lo rellenado en la última página (pagina_hora, pagina_descarte,
//   pagina_confirmar_hora o pagina_cancela).
// Salida: { valido, mensaje, cuerpo, resumen_html }
//   valido       -> true si todo cuadra; false = no se envía nada
//   cuerpo       -> el JSON EXACTO para POST /resultados-llamada (contrato, sección 3)
//   resumen_html -> el resumen para la página de confirmación
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Lo que dejó preparar_ficha: número, tipo de llamada, resultados admitidos y visita pedida.
const ficha = $('preparar_ficha').first().json;
const oportunidad_id = ficha.oportunidad_id;

// Lee lo elegido en una página de resultado. Si esa página no se ha usado en
// esta ejecución, n8n lanza un error: se atrapa y se devuelve undefined.
function eleccionDe(nodo) {
  try { return $(nodo).first().json.decision; } catch (e) { return undefined; }
}
// Gate y seguimiento usan pagina_resultado; la confirmación, pagina_resultado_confirmacion.
const eleccion = eleccionDe('pagina_resultado') ?? eleccionDe('pagina_resultado_confirmacion');

// Texto del desplegable -> resultado que admite el backend.
const RESULTADOS = {
  'Visita acordada': 'visita_acordada',
  'Descartar': 'descartar',
  'Confirmar la hora pedida': 'confirmar_hora',
  'Otra hora': 'otra_hora',
  'El cliente cancela': 'cliente_cancela',
};
// Texto del desplegable -> motivo que admite el backend.
const MOTIVOS = {
  'Precio: le parece caro': 'precio',
  'Plazo: no le encajan los tiempos': 'plazo',
  'No contesta (tras varios intentos)': 'no_contesta',
  'Sigue sin decidirse (última llamada)': 'sin_decision',
  'Proyecto no viable técnicamente': 'proyecto_no_viable',
  'Otro (explícalo en el informe)': 'otro',
};
// Etiquetas para el resumen que verá el operador antes de confirmar.
const ETIQUETAS = {
  visita_acordada: 'Visita acordada', descartar: 'DESCARTAR (definitivo)',
  confirmar_hora: 'Confirmar la hora pedida', otra_hora: 'Otra hora (la pedida se cancela)',
  cliente_cancela: 'EL CLIENTE CANCELA (definitivo)',
};
const TIPOS_LLAMADA = { gate: 'Gate (aprobación manual)', seguimiento: 'Seguimiento del presupuesto', confirmacion_visita: 'Confirmación de visita pedida' };

// Salida de error: así no se envía nada al backend.
function invalido(mensaje) {
  return { json: { valido: false, mensaje, cuerpo: null, resumen_html: '' } };
}
// Escapar texto antes de meterlo en HTML.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
// Una fila "etiqueta: valor" del resumen. El valor SIEMPRE pasa por esc().
function fila(etiqueta, valor) {
  // v2 (14/10): sin style (n8n lo elimina); el valor va en negrita.
  return `<tr><td>${etiqueta}</td><td><strong>${esc(valor)}</strong></td></tr>`;
}
// "2026-10-14" + "11:00" -> "miércoles 14/10/2026 a las 11:00".
// Date.UTC + getUTCDay: la zona horaria del servidor no puede mover el día.
function fechaLegible(fecha, hora) {
  const [a, m, d] = fecha.split('-');
  const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const dia = DIAS[new Date(Date.UTC(Number(a), Number(m) - 1, Number(d))).getUTCDay()];
  return `${dia} ${d}/${m}/${a} a las ${hora}`;
}

// ---- 1. Comprobaciones comunes ----------------------------------------------
if (!oportunidad_id) return invalido('No se ha podido recuperar el número de oportunidad. Vuelve a abrir el formulario.');
// Traducir lo elegido; si no está en el diccionario, mejor parar que adivinar.
const resultado = RESULTADOS[eleccion];
if (!resultado) return invalido(`Resultado no reconocido: "${eleccion}". Avisa al responsable técnico.`);
// Defensa: el resultado tiene que estar entre los que el backend dijo que admite esta llamada.
if (!(ficha.resultados ?? []).includes(resultado)) {
  return invalido(`"${eleccion}" no se admite en esta llamada. Vuelve a abrir el formulario.`);
}
// El informe, sin espacios sobrantes; el backend exige de 1 a 2.000 caracteres.
const informe = String($json.informe ?? '').trim();
if (informe.length === 0) return invalido('El informe de la llamada está vacío.');
if (informe.length > 2000) return invalido(`El informe tiene ${informe.length} caracteres; el máximo es 2.000.`);

// ---- 2. El cuerpo según el resultado (tabla de la sección 3 del contrato) ---
let cuerpo;
let filas = fila('Llamada', TIPOS_LLAMADA[ficha.tipo_llamada] ?? ficha.tipo_llamada) +
            fila('Resultado', ETIQUETAS[resultado]);

if (resultado === 'visita_acordada' || resultado === 'otra_hora') {
  // D32: la fecha, la del día elegido en esta vuelta (la guarda preparar_pagina_hora);
  // la hora, el botón elegido en la página "Hora". Nadie las escribe a mano.
  let fecha = '';
  try { fecha = String($('preparar_pagina_hora').first().json.fecha ?? ''); } catch (e) { fecha = ''; }
  const hora = String($json.hora ?? '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !/^\d{2}:\d{2}$/.test(hora)) {
    return invalido('Falta la fecha o la hora de la visita.');
  }
  // "Otra hora" no puede ser la misma que pidió el cliente (el backend daría 422).
  const vp = ficha.visita_pedida;
  if (resultado === 'otra_hora' && vp && fecha === vp.fecha && hora === vp.hora) {
    return invalido('Es la misma hora que pidió el cliente: vuelve a abrir el formulario y elige "Confirmar la hora pedida".');
  }
  cuerpo = { oportunidad_id, resultado, fecha, hora, informe };
  filas += fila('Visita', fechaLegible(fecha, hora));
} else if (resultado === 'confirmar_hora') {
  // La hora PEDIDA, tal cual la dio la ficha (nadie la escribe a mano).
  const vp = ficha.visita_pedida;
  if (!vp) return invalido('No se encuentra la visita pedida. Vuelve a abrir el formulario.');
  cuerpo = { oportunidad_id, resultado, fecha: vp.fecha, hora: vp.hora, informe };
  filas += fila('Visita', fechaLegible(vp.fecha, vp.hora));
} else {
  // descartar o cliente_cancela: motivo OBLIGATORIO, sin fecha ni hora.
  const motivo = MOTIVOS[$json.motivo];
  if (!motivo) return invalido(`Motivo no reconocido: "${$json.motivo}". Avisa al responsable técnico.`);
  // Quien cancela ha contestado y ha decidido: esos dos motivos no valen (D29.3).
  if (resultado === 'cliente_cancela' && (motivo === 'no_contesta' || motivo === 'sin_decision')) {
    return invalido('Ese motivo no vale cuando el cliente cancela. Elige otro.');
  }
  cuerpo = { oportunidad_id, resultado, motivo, informe };
  filas += fila('Motivo', $json.motivo);
}

// ---- 3. El resumen para la página de confirmación ---------------------------
// El informe, escapado y con sus saltos de línea convertidos en <br>.
const informeHtml = esc(informe).replace(/\r?\n/g, '<br>');
// v2 (14/10): sin style (n8n lo elimina).
const resumen_html =
  `<p><strong>Oportunidad ${esc(oportunidad_id)}</strong></p>` +   // el número, en negrita
  `<table>${filas}` +                                               // las filas del resultado
  `<tr><td>Informe</td><td>${informeHtml}</td></tr>` +              // el informe escrito
  `</table>`;

// Todo listo.
return { json: { valido: true, mensaje: '', cuerpo, resumen_html } };

// ---------------------------------------------------------------------------
// Formulario de llamadas · Traducir la respuesta de POST /resultados-llamada. F2, 2026-10-12.
// 2026-10-13: 409 hueco_ocupado (D31) con sus huecos_libres; NO es aviso técnico.
// 2026-10-14 (D32): en "Visita acordada" y "Otra hora", el 409 hueco_ocupado
//   vuelve a la página "Día" (volver_agenda = true); el 422 fuera_de_rejilla es
//   un fallo del formulario (aviso técnico). Lecturas con .first() (bucles).
// v2, 2026-10-14 (D33): ya no pide anotar la visita a mano; la frase del
//   calendario la añade cerrar_pantalla después de llamar a WF5.
// Entrada ($json): la respuesta COMPLETA { statusCode, headers, body }.
// Salida: { titulo, mensaje, aviso_tecnico, codigo, oportunidad_id,
//           volver_agenda, fecha_ocupada, hora_ocupada }
//   aviso_tecnico -> true si hay que avisar al técnico (lo lee preparar_aviso_tecnico -> WF4)
//   volver_agenda -> true: segun_traduccion vuelve a la página "Día" en vez de terminar
// Textos: secciones 4 y 4b de docs/Contrato_Formulario_Llamadas.md.
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP y cuerpo ("?? {}": objeto vacío si no hay cuerpo).
const estado = $json.statusCode;
const b = $json.body ?? {};
// Lo que se envió (.first() = la última ejecución de preparar_decision).
const enviado = $('preparar_decision').first().json.cuerpo ?? {};
// Número de oportunidad: del cuerpo que se envió.
const op = enviado.oportunidad_id;

// Fecha y hora en español y hora de Madrid, solo para MOSTRAR.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
    year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}
// Atajo para la pantalla final; aviso_tecnico = false y volver_agenda = false salvo que se diga.
function pantalla(titulo, mensaje, aviso_tecnico = false) {
  return { json: { titulo, mensaje, aviso_tecnico, codigo: estado, oportunidad_id: op, volver_agenda: false } };
}
// Motivos del backend -> texto para el operador.
const MOTIVOS = {
  precio: 'precio', plazo: 'plazo', no_contesta: 'no contesta', proyecto_no_viable: 'proyecto no viable',
  otro: 'otro', sin_decision: 'sin decisión en la última llamada',
};

// ---- 1. Éxito: 201 (registrado ahora) o 200 (repetición exacta) ------------
if (estado === 201 || estado === 200) {
  const reg = `(registro nº ${b.llamada_id})`;
  // 200: el backend no ha escrito nada (normal si n8n reintenta).
  if (estado === 200) {
    return pantalla('Ya estaba registrado', `Oportunidad ${op}: este mismo resultado ya estaba registrado ${reg}. No se ha cambiado nada.`);
  }
  // 201 con visita (visita acordada, hora confirmada u otra hora).
  if (['visita_acordada', 'confirmar_hora', 'otra_hora'].includes(b.resultado)) {
    const cancelada = b.resultado === 'otra_hora' ? ' La hora que había pedido el cliente queda cancelada.' : '';
    return pantalla('Visita registrada',
      `Oportunidad ${op}: visita confirmada el ${fecha(b.fecha_visita)} ${reg}.${cancelada}`);
  }
  // 201 de descarte.
  if (b.resultado === 'descartar') {
    return pantalla('Descarte registrado',
      `Oportunidad ${op} descartada, motivo: ${MOTIVOS[b.motivo] ?? b.motivo} ${reg}. La oportunidad queda cerrada como perdida.`);
  }
  // 201 de cancelación del cliente.
  if (b.resultado === 'cliente_cancela') {
    return pantalla('Cancelación registrada',
      `Oportunidad ${op}: el cliente cancela, motivo: ${MOTIVOS[b.motivo] ?? b.motivo} ${reg}. La visita pedida queda cancelada y la oportunidad cerrada como perdida.`);
  }
  // Un resultado nuevo que este nodo no conoce: se enseña tal cual.
  return pantalla('Resultado registrado', `Oportunidad ${op}: ${b.resultado} ${reg}.`);
}

// ---- 2. Rechazos de negocio: {"detail": {"motivo": ..., "mensaje": ...}} ----
// "?." evita romper si detail no es un objeto (un 422 de forma trae una lista).
const motivo = b.detail?.motivo;
const mensajeBackend = b.detail?.mensaje ?? '';
const NADA = ' No se ha registrado nada.';

// 409 hueco_ocupado (D31/D32): la hora choca con otra visita. Caso normal del
// negocio (un solo técnico), NO un fallo: sin aviso técnico.
if (estado === 409 && motivo === 'hueco_ocupado') {
  // "Visita acordada" u "Otra hora": la hora salió de la agenda y alguien la cogió
  // entre la página "Hora" y el envío. Se vuelve a "Día", recalculada (contrato 4b).
  if (enviado.resultado === 'visita_acordada' || enviado.resultado === 'otra_hora') {
    const r = pantalla('Hora ocupada', `Esa hora se acaba de ocupar.${NADA}`);
    r.json.volver_agenda = true;                 // segun_traduccion -> entrar_agenda
    r.json.fecha_ocupada = enviado.fecha;        // para el aviso de la página "Día"
    r.json.hora_ocupada = enviado.hora;
    return r;
  }
  // "Confirmar la hora pedida": la hora la pidió el cliente y ya no está libre.
  return pantalla('La hora pedida ya no está libre',
    `La hora que pidió el cliente ya está ocupada por otra visita.${NADA} ` +
    'Vuelve a abrir el formulario y elige "Otra hora" para acordar una nueva con él.');
}

// Fecha u hora no válidas: el mensaje del backend explica la regla y las franjas.
if (estado === 422 && ['fecha_pasada', 'fin_de_semana', 'fuera_de_franja'].includes(motivo)) {
  return pantalla('Fecha u hora no válidas', `${mensajeBackend}${NADA} Vuelve a abrir el formulario y elige otra fecha u hora.`);
}
// D32: fuera de la rejilla no debería salir nunca (las horas vienen de la agenda):
// si sale, el formulario envía una hora que no vino de la consulta -> aviso técnico.
if (estado === 422 && motivo === 'fuera_de_rejilla') {
  return pantalla('Hora no válida', `${mensajeBackend}${NADA} Avisa al responsable técnico.`, true);
}
if (estado === 422 && motivo === 'misma_hora_pedida') {
  return pantalla('Es la hora que pidió', `Es la hora que pidió el cliente: elige "Confirmar la hora pedida".${NADA}`);
}
// Conflictos (409) y oportunidad inexistente (404): textos del contrato.
const MENSAJES = {
  resultado_ya_registrado: 'Esta llamada ya tiene un resultado registrado (es definitivo).',
  resultado_no_admitido: 'La situación del cliente ha cambiado desde que abriste la ficha: vuelve a abrir el formulario.',
  visita_cambiada: 'El cliente ha cambiado la hora pedida: vuelve a abrir el formulario y confírmale la nueva.',
  estado_no_permitido: 'Esta oportunidad no tiene ninguna llamada pendiente.',
  sin_presupuesto: 'Todavía no tiene presupuesto.',
  visita_activa_existente: 'Ya tiene una visita activa.',
  oportunidad_no_encontrada: 'Oportunidad no encontrada.',
};
if (MENSAJES[motivo]) return pantalla('No se ha podido registrar', MENSAJES[motivo] + NADA);
// Los cuatro motivos del seguimiento: un texto común más el del backend.
if (['plazo_no_cumplido', 'contacto_registrado', 'visita_existente', 'con_gate'].includes(motivo)) {
  return pantalla('No se ha podido registrar', `Esta oportunidad no está en el seguimiento ahora mismo. ${mensajeBackend}${NADA}`);
}

// ---- 3. Errores técnicos: el operador no puede arreglarlos -> aviso técnico --
if (estado === 401) {
  return pantalla('Error de configuración', `El formulario no tiene una llave válida.${NADA} Avisa al responsable técnico.`, true);
}
if (estado === 422) {
  // 422 sin motivo = el cuerpo no tiene la forma esperada: fallo nuestro, no del operador.
  return pantalla('Error en los datos enviados', `El sistema ha rechazado el formato de los datos.${NADA} Avisa al responsable técnico.`, true);
}
if (estado === 503) {
  return pantalla('Sistema no disponible', `Falta configuración en el sistema.${NADA} Avisa al responsable técnico.`, true);
}
// Cualquier otro código (500...): se enseña para poder buscarlo.
return pantalla('Error inesperado', `Código ${estado}.${NADA} Avisa al responsable técnico.`, true);

// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar el aviso técnico. F4, 2026-10-13.
// Revisión 13/10 (prueba 81): textoError lee code, message y description,
// porque los errores de red de n8n pueden traer SOLO "code" (p. ej.
// ERR_INVALID_HTTP_TOKEN, ECONNREFUSED) y el aviso salía "error sin mensaje".
// D32, 2026-10-14: recibe también de la agenda (leer_dias, leer_horas y los
// nodos agenda_ok, hora_ok y segun_dia, que mandan sus errores ya preparados
// en { aviso_tecnico, nodo_error, mensaje_tecnico }).
// Orígenes (se sabe cuál con $prevNode.name):
//   - traducir_resultado    -> respuesta de POST /resultados-llamada (avisa si aviso_tecnico)
//   - caso_registrable      -> rama "no registrable" de la ficha (avisa si aviso_tecnico)
//   - leer_ficha, leer_dias, leer_horas -> salida de ERROR: sin respuesta del backend
//   - registrar_resultado   -> salida de ERROR: conexión perdida al registrar
//   - agenda_ok, hora_ok, segun_dia -> errores de la agenda, ya preparados
//   - cerrar_pantalla       -> v2 (D33): WF5 NO se pudo ni ejecutar (avisa si aviso_calendario).
//                              Si WF5 se ejecutó y falló, WF5 ya avisó por su cuenta.
// Mode: Run Once for All Items, para poder devolver [] (= no avisar, la rama se para).
// Salida: 0 elementos, o 1 con los 5 datos que espera WF4_aviso_tecnico:
//   { flujo, nodo, mensaje_error, oportunidad_id, ejecucion_id }
// RGPD: nunca se envían datos del cliente ni el cuerpo de la petición; solo
// códigos, nombres de nodos, fechas de la agenda y el número de oportunidad.
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Nombre del nodo que nos ha mandado el dato en esta ejecución.
const origen = $prevNode.name;
// El único elemento que llega (el formulario procesa un caso cada vez).
const dato = $input.first().json;

// Número que escribió administración en la primera página. Existe siempre,
// incluso cuando el backend no respondió. try/catch: si no se pudiera leer, null.
let oportunidad_id = null;
try {
  oportunidad_id = $('On form submission').first().json.oportunidad_id ?? null;
} catch (e) {
  oportunidad_id = null;
}

// Texto del error que deja n8n en la salida de error de un nodo HTTP.
// Puede venir como texto o como objeto. Si es objeto, se juntan los campos de
// texto que traiga: code (siempre en errores de red), message y description.
// Nunca se envía el objeto entero (podría llevar la petición completa).
function textoError(j) {
  const e = j.error;                                   // el error, si n8n lo dejó
  if (!e) return 'sin detalle del error';              // no llegó nada
  if (typeof e === 'string') return e;                 // ya es un texto
  // Los tres campos candidatos, en este orden; se quedan solo los textos no vacíos.
  const partes = [e.code, e.message, e.description]
    .filter((x) => typeof x === 'string' && x.trim() !== '');
  // Si hay alguno, se unen con " · "; si no, se dice que no trae texto.
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto (revisar la ejecución)';
}

// Los nodos HTTP que leen (sin escribir nada) y qué leen: para el texto del aviso.
const LECTURAS = {
  leer_ficha: 'leer la ficha',
  leer_dias: 'leer los días con hueco (GET /huecos-libres)',
  leer_horas: 'leer las horas libres de un día (GET /huecos-libres?fecha=...)',
};

let nodo;            // el paso que ha fallado (lo verá el técnico)
let mensaje_error;   // qué ha pasado, en una línea

if (origen === 'traducir_resultado') {
  // El backend respondió, pero con un error técnico (401, 422 de forma, 503, 500...).
  if (dato.aviso_tecnico !== true) return [];          // error del operador o éxito: no avisar
  nodo = 'registrar_resultado';
  mensaje_error = `POST /resultados-llamada respondió ${dato.codigo} (${dato.titulo}). No se ha registrado nada.`;
} else if (origen === 'caso_registrable') {
  // La ficha no se puede registrar: solo se avisa si es un fallo técnico.
  if (dato.aviso_tecnico !== true) return [];          // 404, 422, ya registrado, nada: no avisar
  nodo = 'leer_ficha';
  mensaje_error = `GET /oportunidades/{id}/ficha respondió ${dato.codigo}. ${dato.mensaje}`;
} else if (LECTURAS[origen]) {
  // Salida de error de un nodo HTTP de lectura: la petición no llegó a tener
  // respuesta (backend apagado, sin red, o configuración inválida).
  nodo = origen;
  mensaje_error = `Sin respuesta del backend al ${LECTURAS[origen]}: ${textoError(dato)}`;
} else if (origen === 'registrar_resultado') {
  // Se cortó la conexión DURANTE el registro: puede que se haya escrito o no.
  nodo = 'registrar_resultado';
  mensaje_error = `Sin respuesta durante POST /resultados-llamada; NO se sabe si se registró: ${textoError(dato)}`;
} else if (['agenda_ok', 'hora_ok', 'segun_dia'].includes(origen)) {
  // Errores de la agenda: el nodo que los detectó ya dejó el paso y el texto.
  if (dato.aviso_tecnico !== true) return [];          // por seguridad: solo los marcados
  nodo = String(dato.nodo_error ?? origen);
  mensaje_error = String(dato.mensaje_tecnico ?? 'Error de la agenda sin detalle.');
} else if (origen === 'cerrar_pantalla') {
  // v2 (D33): la llamada a WF5 falló entera (sin resumen de WF5): nadie ha avisado aún.
  if (dato.aviso_calendario !== true) return [];        // calendario bien, o WF5 ya avisó
  nodo = 'llamar_calendario';
  mensaje_error = String(dato.mensaje_tecnico ?? 'Fallo al llamar a WF5 sin detalle.');
} else {
  // Alguien ha conectado este nodo a otro sitio: se avisa para que se revise.
  nodo = origen;
  mensaje_error = 'Origen no previsto en preparar_aviso_tecnico: revisar las conexiones del flujo.';
}

// Los 5 datos para WF4_aviso_tecnico. $workflow.name = nombre de este flujo;
// $execution.id = número de esta ejecución (para buscarla en Executions).
return [{
  json: {
    flujo: $workflow.name,
    nodo,
    mensaje_error,
    oportunidad_id,
    ejecucion_id: String($execution.id),
  },
}];

// ---------------------------------------------------------------------------
// Formulario de llamadas · Entrar en la agenda (D32). 2026-10-14.
// Recibe de CUATRO sitios (se sabe cuál con $prevNode.name):
//   - segun_decision              -> "Visita acordada" (primera vez)
//   - segun_decision_confirmacion -> "Otra hora" (primera vez)
//   - segun_hora                  -> "Ninguna le va bien": el cliente quiere otro día
//   - segun_traduccion            -> 409 hueco_ocupado: alguien cogió la hora entre
//                                    la página "Hora" y el envío
// Salida (1 elemento): { vuelta, aviso_html, resultado_texto, oportunidad_id }
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// En un bucle este nodo se ejecuta varias veces: quien lo lea usa .first(),
// que en n8n devuelve el elemento de su ÚLTIMA ejecución.
// ---------------------------------------------------------------------------

// Nombre del nodo que nos ha mandado el dato en esta vuelta.
const origen = $prevNode.name;
// El único elemento que llega (el formulario procesa un caso cada vez).
const dato = $input.first().json;

// Escapar texto antes de meterlo en HTML (las fechas y horas vienen del backend,
// pero se escapan igual: es la regla del flujo para TODO lo que va a HTML).
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < y > : impiden abrir etiquetas HTML
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')   // comillas: impiden salir de un atributo
    .replace(/'/g, '&#39;');
}

// Lee lo elegido en una página de resultado; si esa página no se usó en esta
// ejecución, n8n lanza un error: se atrapa y se devuelve undefined.
function eleccionDe(nodo) {
  try { return $(nodo).first().json.decision; } catch (e) { return undefined; }
}
// "Visita acordada" (Gate o seguimiento) u "Otra hora" (confirmación).
const resultado_texto = eleccionDe('pagina_resultado') ?? eleccionDe('pagina_resultado_confirmacion') ?? 'Visita';
// El número de oportunidad, de la ficha (preparar_ficha se ejecuta una sola vez).
const oportunidad_id = $('preparar_ficha').first().json.oportunidad_id;

// Por defecto: primera vez, sin aviso.
let vuelta = 'inicio';
// El aviso que se enseñará arriba de la página "Día" (vacío = ninguno).
let aviso_html = '';

if (origen === 'segun_hora') {
  // El cliente no quiso ninguna hora de ese día: se vuelve a elegir día.
  vuelta = 'otro_dia';
  // Aviso informativo (v2: sin color, n8n borra style).
  aviso_html = '<p>Ninguna hora de ese día le iba bien: elige otro día.</p>';
} else if (origen === 'segun_traduccion') {
  // 409 hueco_ocupado al registrar: la hora se ocupó mientras se rellenaba.
  vuelta = 'hueco_ocupado';
  // Aviso con ⚠️ y negrita (v2: sin color), con el día y la hora que se intentaron (nunca de quién es la otra visita).
  aviso_html =
    `<p>⚠️ <strong>Atención:</strong> la hora ${esc(dato.hora_ocupada ?? '')} ` +
    `del ${esc(dato.fecha_ocupada ?? '')} se acaba de ocupar (otra reserva entró mientras tanto). ` +
    `<strong>No se ha registrado nada.</strong> Elige otra con el cliente.</p>`;
}
// Cualquier otro origen (segun_decision o segun_decision_confirmacion): primera vez.

// Un solo elemento con todo lo que necesitan las páginas siguientes.
return [{ json: { vuelta, aviso_html, resultado_texto, oportunidad_id } }];

// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar la página "Día" (D32). 2026-10-14.
// Entrada ($json): la respuesta COMPLETA de GET /huecos-libres (modo días),
//   { statusCode, headers, body } (opción "Include Response Headers and Status").
// Salida (1 elemento):
//   ok: true  -> { campos, titulo, dias }: campos = los campos de la página en JSON
//                (Define Form: Using JSON); dias = la lista del backend, para
//                traducir después la opción elegida a su fecha.
//   ok: false -> { mensaje, aviso_tecnico, nodo_error, mensaje_tecnico, codigo }
// Contrato: docs/Contrato_Formulario_Llamadas.md, sección 4b.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP y cuerpo ("?? {}": objeto vacío si no hay cuerpo).
const estado = $input.first().json.statusCode;
const b = $input.first().json.body ?? {};
// Lo que dejó entrar_agenda en ESTA vuelta (.first() = su última ejecución).
const ctx = $('entrar_agenda').first().json;
// Texto fijo de la opción del calendario (contrato 4b: no choca con ninguna etiqueta).
const OTRO = 'Otro día más adelante';

// Escapar texto antes de meterlo en HTML.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < y > : impiden abrir etiquetas HTML
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')   // comillas: impiden salir de un atributo
    .replace(/'/g, '&#39;');
}

// ---- 1. El backend no respondió 200: fallo técnico, aviso y fin -------------
if (estado !== 200) {
  return [{
    json: {
      ok: false,                                         // va a la pantalla de error
      aviso_tecnico: true,                               // lo lee preparar_aviso_tecnico
      mensaje: `No se han podido leer los huecos libres (código ${estado}). No se ha registrado nada. Avisa al responsable técnico.`,
      nodo_error: 'leer_dias',                           // el paso que ha fallado
      mensaje_tecnico: `GET /huecos-libres respondió ${estado}.`, // para el técnico
      codigo: estado,                                    // el código HTTP
    },
  }];
}

// ---- 2. Los días: solo los que traen etiqueta y fecha con buena forma -------
// Defensa: si el backend mandara algo raro, se ignora en vez de enseñarlo.
const dias = (Array.isArray(b.dias) ? b.dias : [])
  .filter((d) => d && typeof d.etiqueta === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha ?? '')));

// Opciones del desplegable: una por día (su etiqueta, tal cual) y la del calendario al final.
const opciones = dias.map((d) => ({ option: d.etiqueta })).concat([{ option: OTRO }]);

// ---- 3. El texto de arriba de la página -------------------------------------
let html =
  `<p>Oportunidad <strong>${esc(ctx.oportunidad_id)}</strong> · <strong>${esc(ctx.resultado_texto)}</strong>. ` +
  `Pregunta al cliente qué día le viene bien. Solo aparecen los días con alguna hora libre ` +
  `y, en cada uno, sus horas libres de mañana y de tarde.</p>`;
// El aviso de la vuelta (otro día u hora ocupada), si lo hay.
html += ctx.aviso_html ?? '';
// Sin ningún día con hueco: se explica y solo queda el calendario.
if (dias.length === 0) {
  // v2: ⚠️ y negrita en vez de color (n8n borra style).
  html += `<p>⚠️ <strong>No queda ninguna hora libre</strong> en los próximos días laborables: elige "${OTRO}".</p>`;
}

// ---- 4. Los campos de la página (formato "Using JSON" del nodo n8n Form) ----
const campos = [
  // El texto de arriba.
  { fieldType: 'html', html },
  // El desplegable de días (obligatorio).
  {
    fieldLabel: 'Día de la visita',
    fieldName: 'dia',
    fieldType: 'dropdown',
    fieldOptions: { values: opciones },
    requiredField: true,
  },
];

// Todo listo: los campos, el título y la lista de días para traducir la elección.
return [{
  json: {
    ok: true,
    campos,
    titulo: `Oportunidad ${ctx.oportunidad_id} · Elegir día`,
    dias,
  },
}];

// ---------------------------------------------------------------------------
// Formulario de llamadas · Traducir el día elegido a su fecha (D32). 2026-10-14.
// Entrada ($json): lo rellenado en pagina_dia, { dia: "<etiqueta elegida>" }.
// Salida (1 elemento) con "destino", que lee el Switch segun_dia:
//   'horas'      -> { fecha: "YYYY-MM-DD" } : se piden las horas de ese día
//   'calendario' -> el operador eligió "Otro día más adelante"
//   'error'      -> la etiqueta no está en la lista (no debería pasar nunca)
// El desplegable devuelve el TEXTO de la opción: se busca en la lista que dio
// el backend en ESTA vuelta (contrato 4b). Nunca se deduce la fecha del texto.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Texto fijo de la opción del calendario (el mismo que en preparar_pagina_dia).
const OTRO = 'Otro día más adelante';
// Lo elegido en la página "Día".
const elegido = String($input.first().json.dia ?? '');

// "Otro día más adelante": a la página del calendario.
if (elegido === OTRO) {
  return [{ json: { destino: 'calendario' } }];
}

// La lista de días de esta vuelta (.first() = la última ejecución de preparar_pagina_dia).
const dias = $('preparar_pagina_dia').first().json.dias ?? [];
// El día cuya etiqueta coincide EXACTAMENTE con lo elegido.
const d = dias.find((x) => x.etiqueta === elegido);

// No encontrado: fallo del formulario (la opción no salió de la lista). Aviso técnico.
if (!d) {
  return [{
    json: {
      destino: 'error',                                   // al final con error
      ok: false,                                          // para la pantalla de error
      aviso_tecnico: true,                                // lo lee preparar_aviso_tecnico
      mensaje: 'No se reconoce el día elegido. No se ha registrado nada. Vuelve a abrir el formulario y avisa al responsable técnico.',
      nodo_error: 'pagina_dia',                           // el paso que ha fallado
      mensaje_tecnico: `Día elegido que no está en la lista de GET /huecos-libres: "${elegido}".`,
    },
  }];
}

// Encontrado: su fecha, para pedir las horas libres de ese día.
return [{ json: { destino: 'horas', fecha: d.fecha } }];

// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar la página "Hora" (D32). 2026-10-14.
// Entrada ($json): la respuesta COMPLETA de GET /huecos-libres?fecha=... (modo un día).
// Se llama AL ABRIR la página: si durante la llamada alguien cogió una hora,
// aquí ya no aparece (contrato 4b).
// Salida (1 elemento):
//   ok: true  -> { campos, titulo, fecha }
//   ok: false -> { mensaje, aviso_tecnico, nodo_error, mensaje_tecnico, codigo }
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP y cuerpo.
const estado = $input.first().json.statusCode;
const b = $input.first().json.body ?? {};
// Lo que dejó entrar_agenda en esta vuelta.
const ctx = $('entrar_agenda').first().json;
// Texto fijo de la opción que vuelve a la página "Día" (contrato 4b).
const NINGUNA = 'Ninguna le va bien → elegir otro día';

// Escapar texto antes de meterlo en HTML.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')     // < y > : impiden abrir etiquetas HTML
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')   // comillas: impiden salir de un atributo
    .replace(/'/g, '&#39;');
}

// ---- 1. El backend no respondió 200: fallo técnico, aviso y fin -------------
// (Un 422 aquí = fecha mal escrita: no lo puede provocar el operador, que elige
// de una lista o de un calendario; por eso también es técnico.)
if (estado !== 200) {
  return [{
    json: {
      ok: false,
      aviso_tecnico: true,
      mensaje: `No se han podido leer las horas libres (código ${estado}). No se ha registrado nada. Avisa al responsable técnico.`,
      nodo_error: 'leer_horas',
      mensaje_tecnico: `GET /huecos-libres?fecha=... respondió ${estado}.`,
      codigo: estado,
    },
  }];
}

// ---- 2. Las horas: solo textos con forma HH:MM ------------------------------
const filtrar = (lista) => (Array.isArray(lista) ? lista : []).filter((h) => typeof h === 'string' && /^\d{2}:\d{2}$/.test(h));
// Todas juntas (las opciones), y por franja (para el texto de arriba).
const horas = filtrar(b.horas);
const manana = filtrar(b.manana);
const tarde = filtrar(b.tarde);

// "2026-10-15" + "jueves" -> "Jueves 15/10/2026" (se recorta el texto: sin zonas horarias).
const fecha = String(b.fecha ?? '');
const [a, m, d] = fecha.split('-');
const diaSemana = String(b.dia_semana ?? '');
const diaLegible = `${diaSemana.charAt(0).toUpperCase()}${diaSemana.slice(1)} ${d}/${m}/${a}`;

// Por qué no hay horas, si no las hay (el backend lo dice en sin_horas_motivo).
const MOTIVOS_SIN_HORAS = {
  dia_completo: 'Ese día ya no queda ninguna hora libre (se han ocupado todas).',
  fin_de_semana: 'Es fin de semana: no hay visitas.',
  fecha_pasada: 'Esa fecha ya ha pasado.',
};

// El informe que ya se escribió en una vuelta anterior, para no perderlo.
// Si la página "Hora" todavía no se ha usado, n8n lanza un error: texto vacío.
let informePrevio = '';
try { informePrevio = String($('pagina_hora').first().json.informe ?? ''); } catch (e) { informePrevio = ''; }

// ---- 3. El texto de arriba de la página -------------------------------------
let html = `<p><strong>${esc(diaLegible)}</strong> · Oportunidad ${esc(ctx.oportunidad_id)} · ${esc(ctx.resultado_texto)}</p>`;
if (horas.length > 0) {
  // Las horas libres de este momento, por franja (una franja vacía no se escribe).
  const partes = [];
  if (manana.length > 0) partes.push(`mañana: ${manana.join(' · ')}`);
  if (tarde.length > 0) partes.push(`tarde: ${tarde.join(' · ')}`);
  html += `<p>Horas libres ahora mismo — ${esc(partes.join(' — '))}.</p>`;
} else {
  // Ninguna hora: se dice por qué y solo queda volver a elegir día.
  const motivo = MOTIVOS_SIN_HORAS[b.sin_horas_motivo] ?? 'Ese día no hay ninguna hora libre.';
  // v2: ⚠️ y negrita en vez de color (n8n borra style).
  html += `<p>⚠️ <strong>${esc(motivo)}</strong> Elige "${esc(NINGUNA)}".</p>`;
}

// ---- 4. Los campos de la página ---------------------------------------------
const campos = [
  // El texto de arriba.
  { fieldType: 'html', html },
  // Las horas como botones (radio), más la opción de volver a "Día". Obligatorio.
  {
    fieldLabel: 'Hora de la visita',
    fieldName: 'hora',
    fieldType: 'radio',
    fieldOptions: { values: horas.map((h) => ({ option: h })).concat([{ option: NINGUNA }]) },
    requiredField: true,
  },
  // El informe: obligatorio si hay horas (hará falta para registrar); si no las
  // hay, opcional, y conserva lo ya escrito para la siguiente vuelta.
  {
    fieldLabel: 'Informe de la llamada',
    fieldName: 'informe',
    fieldType: 'textarea',
    placeholder: 'Qué se habló, qué se acordó y dudas del cliente.',
    defaultValue: informePrevio,
    requiredField: horas.length > 0,
  },
];

// Todo listo: los campos, el título y la fecha (la usará preparar_decision).
return [{
  json: {
    ok: true,
    campos,
    titulo: `Oportunidad ${ctx.oportunidad_id} · Elegir hora`,
    fecha,
  },
}];

// ---------------------------------------------------------------------------
// Formulario de llamadas · Preparar las llamadas a WF5 (D33). v2, 2026-10-14.
// Lee la respuesta de POST /resultados-llamada y decide qué cambios hay que
// copiar al calendario. Lo decide la RESPUESTA del backend, no el resultado
// elegido: el backend dice qué visita queda confirmada y cuál se canceló.
//   visita_cancelada_id  -> WF5 'borrar' esa visita   (otra_hora, cliente_cancela)
//   visita_id            -> WF5 'guardar' confirmada  (visita_acordada, confirmar_hora, otra_hora)
// También en un 200 (repetición): WF5 no duplica nunca, y así se recupera un
// calendario que falló la primera vez.
// Salida: 1 elemento por llamada a WF5, o 1 elemento { sin_calendario: true }.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// La respuesta del registro (.first() = la última ejecución de registrar_resultado).
const resp = $('registrar_resultado').first().json;
const estado = resp.statusCode;                       // 201, 200, 409, 422...
const b = resp.body ?? {};                            // el cuerpo ("?? {}": vacío si no hay)
// La ficha: de ahí salen el nombre y el tipo de reforma para el título del evento.
const ficha = $('preparar_ficha').first().json;

// Sin registro (cualquier error): nada que copiar.
if (estado !== 201 && estado !== 200) return [{ json: { sin_calendario: true } }];

// Lo común a todas las llamadas. Textos vacíos en vez de null: WF5 no los necesita
// para borrar, y así ningún campo llega vacío de tipo.
const comun = {
  nombre: ficha.nombre ?? '',                         // solo el nombre (RGPD: nada de contacto)
  tipo_reforma: ficha.tipo_reforma ?? '',             // el código (bano, cocina...)
  oportunidad_id: b.oportunidad_id ?? ficha.oportunidad_id,  // para el enlace a la ficha
};

const llamadas = [];                                  // las llamadas a WF5, en orden
// 1. La visita pedida que se ha cancelado: su evento amarillo se borra.
if (b.visita_cancelada_id) {
  llamadas.push({ accion: 'borrar', visita_id: b.visita_cancelada_id,
                  estado_visita: '', inicio: '', fin: '', ...comun });
}
// 2. La visita que queda confirmada: se crea, o se pasa de amarillo a verde.
//    Inicio y fin, tal cual los da el backend (n8n no suma la duración, D33).
if (b.visita_id) {
  llamadas.push({ accion: 'guardar', visita_id: b.visita_id, estado_visita: 'confirmada',
                  inicio: b.fecha_visita ?? '', fin: b.fecha_fin_visita ?? '', ...comun });
}

// Descartar (sin visitas): nada que copiar.
if (llamadas.length === 0) return [{ json: { sin_calendario: true } }];
// Un elemento por llamada: llamar_calendario (modo "each") llama a WF5 una vez por cada uno.
return llamadas.map((j) => ({ json: j }));

// ---------------------------------------------------------------------------
// Formulario de llamadas · Texto de la pantalla final (D33). v2, 2026-10-14.
// Recibe de dos sitios (se sabe cuál con $prevNode.name):
//   - necesita_calendario -> no había nada que copiar: el texto de traducir_resultado tal cual
//   - llamar_calendario   -> 1 resultado de WF5 por llamada: { ok, accion, mensaje, ... },
//                            o { error } si WF5 no se pudo ni ejecutar
// Salida (1 elemento): { titulo, mensaje, aviso_calendario, mensaje_tecnico }
//   aviso_calendario -> true SOLO si WF5 no se ejecutó (si se ejecutó y falló, ya avisó él)
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El texto del registro (.first() = la última ejecución, también tras el bucle de la agenda).
const t = $('traducir_resultado').first().json;
// Atajo para la salida.
const salida = (titulo, mensaje, aviso_calendario = false, mensaje_tecnico = '') =>
  [{ json: { titulo, mensaje, aviso_calendario, mensaje_tecnico } }];

// Sin calendario (descarte o cualquier error del registro): el texto de siempre.
if ($prevNode.name !== 'llamar_calendario') return salida(t.titulo, t.mensaje);

// Lo que se pidió a WF5 y lo que contestó, en el mismo orden.
const pedidas = $('preparar_calendario').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json);
// ¿Había que guardar una visita? (decide el título)
const hayGuardar = pedidas.some((p) => p.accion === 'guardar');

// Texto de un error de n8n sin enviar el objeto entero (podría llevar datos).
function textoError(e) {
  if (!e) return 'sin detalle';
  if (typeof e === 'string') return e;
  const partes = [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto';
}

// Fallo de la LLAMADA: falta algún resultado o alguno no trae "ok" (WF5 no llegó a ejecutarse).
const falloLlamada = resultados.length !== pedidas.length || resultados.some((r) => typeof r.ok !== 'boolean');
// Fallo DENTRO de WF5: se ejecutó, devolvió ok = false y ya mandó su aviso técnico.
const falloWf5 = resultados.some((r) => r.ok === false);

if (falloLlamada || falloWf5) {
  // El registro SÍ está hecho: que nadie lo repita, y que se sepa que el calendario no cuadra.
  const titulo = hayGuardar ? 'Visita registrada, pero NO copiada al calendario' : 'Registrado, pero el calendario no se ha actualizado';
  const mensaje = `${t.mensaje} ⚠️ Atención: el registro SÍ está guardado, no lo repitas. ` +
    'No se ha podido actualizar el calendario "Visitas técnicas — Reformas Amedida": el responsable técnico ya ha recibido un aviso.';
  // Solo si WF5 no se ejecutó hace falta que este flujo avise (si no, WF4 llegaría dos veces).
  const tecnico = falloLlamada
    ? `WF5 no se pudo ejecutar (${resultados.length} de ${pedidas.length} respuestas): ` +
      resultados.map((r) => textoError(r.error)).join(' | ')
    : '';
  return salida(titulo, mensaje, falloLlamada, tecnico);
}

// Todo bien. 201 con visita: el título que pide D33. 200: el título de siempre.
const titulo = (t.codigo === 201 && hayGuardar) ? 'Visita registrada y añadida al calendario' : t.titulo;
// La frase del calendario según lo que se hizo.
let frase;
if (hayGuardar && pedidas.length > 1) frase = ' Calendario actualizado: la hora anterior se ha quitado y la nueva está añadida.';
else if (hayGuardar) frase = ' Visita añadida al calendario "Visitas técnicas — Reformas Amedida".';
else frase = ' La visita pedida se ha quitado del calendario.';
return salida(titulo, t.mensaje + frase);
